mapper.select:
SELECT ald.annual_leave_code, -- 연차관리코드 ald.annual_leave_detail_seq, -- 연차상세관리번호 al.user_id, -- 사번 um.user_name, -- 성명 dm.dept_name, -- 부서명 cmcj.code_name as job_title, -- 직위직급 cmcl.code_name as leave_type, -- 신청구분 ald.used_days, -- 사용일수 ald.leave_start_date as annualStartDate, -- 연차시작일 ald.leave_end_date as annualEndDate, -- 연차종료일 ald.leave_apply_date, -- 연차신청일 ald.rm -- 사유
FROM tb_annual_leave_detail ald JOIN tb_annual_leave al ON al.annual_leave_code = ald.annual_leave_code
JOIN tb_user_master um ON um.user_id = al.user_id
JOIN tb_dept_master dm ON dm.dept_code = um.dept
JOIN tb_cm_code cmcj ON cmcj.code = um.job_title
JOIN tb_cm_code cmcl ON cmcl.code = ald.leave_type WHERE 1=1
AND ald.company_code = #{companyCode}
AND al.user_id = #{userId}
AND ald.leave_start_date >= TO_DATE(#{annualStartDateSearch}, 'YYYY-MM-DD')
AND ald.leave_end_date <= #{annualStartEndSearch}
AND ald.leave_apply_date >= #{leaveApplyStartDateSearch}
AND ald.leave_apply_date <= #{leaveApplyEndDateSearch}

SELECT al.annual_leave_code, al.company_code, al.user_id, al.grant_year, al.total_grant_days, al.total_used_days, al.remaining_days, al.expiry_date, um.user_name, dm.dept_name, ccj.code_name as job_title FROM tb_annual_leave al JOIN tb_user_master um ON um.user_id = al.user_id JOIN tb_dept_master dm ON dm.dept_code = um.dept JOIN tb_cm_code ccj ON ccj.code = um.job_title WHERE 1=1 AND al.grant_year = TO_CHAR(sysdate, 'yyyy')
AND al.user_id = #{userId}
AND al.company_code = #{companyCode}

mapper.update:
UPDATE tb_annual_leave
SET    total_used_days = total_used_days + #{usedDays},
       remaining_days = remaining_days - #{usedDays}
WHERE  user_id = #{userId}
  AND  grant_year = TO_CHAR(sysdate, 'yyyy')
